_thread_idle=threading.local()

def clear_idle():
    physical=getattr(_thread_idle,'physical',None)
    _thread_idle.physical=None
    if physical is not None:
        physical['retired']=True
        try:physical['connection'].close()
        except sqlite3.Error:pass

def _factory_identity(factory):
    return (id(getattr(factory,'__func__',factory)),id(getattr(factory,'__self__',None)))

def _take_idle(factory,target):
    physical=getattr(_thread_idle,'physical',None)
    if physical is None:return None
    _thread_idle.physical=None
    try:
        clean=(physical['owner']==(os.getpid(),threading.get_ident())
            and physical['factory_identity']==_factory_identity(factory)
            and physical['target']==target and not physical['dirty']
            and not physical['connection'].in_transaction
            and physical['connection'].total_changes==0
            and _current_identity(physical['identity'])==physical['identity'])
    except (sqlite3.Error,OSError):clean=False
    if clean:return physical
    physical['retired']=True
    try:physical['connection'].close()
    except sqlite3.Error:pass
    return None

def _keep_idle(state,physical):
    if (not state['target'] or physical['dirty'] or physical['retired']
            or physical['connection'].in_transaction or physical['connection'].total_changes):
        return False
    # Main DB identity, exact factory and owner fence every future borrow.
    if physical['identity'] is None or physical['identity'][0]!=state['target']:return False
    clear_idle()
    physical.update(owner=(os.getpid(),threading.get_ident()),target=state['target'],
        factory_identity=state['factory_identity'],factory_ref=state['factory_ref'])
    _thread_idle.physical=physical
    return True
