class Cursor:
    def __init__(self,lease,cursor):
        object.__setattr__(self,'_lease',lease);object.__setattr__(self,'_cursor',cursor)
        object.__setattr__(self,'_closed',False);lease._cursors.add(self)
    @property
    def connection(self):return self._lease
    def _check(self):
        self._lease._check()
        if self._closed:raise sqlite3.ProgrammingError('Cannot operate on a closed cursor.')
    def close(self):
        if not self._closed:
            object.__setattr__(self,'_closed',True)
            try:self._cursor.close()
            except sqlite3.ProgrammingError:pass
    def __getattr__(self,name):
        value=getattr(self._cursor,name)
        if getattr(value,'__self__',None) is not self._cursor:return value
        def call(*args,**kwargs):
            self._check();result=value(*args,**kwargs)
            return self if result is self._cursor else result
        return call
    def __setattr__(self,name,value):
        if name.startswith('_'):object.__setattr__(self,name,value)
        else:setattr(self._cursor,name,value)
    def __iter__(self):self._check();return self
    def __next__(self):self._check();return next(self._cursor)

class Lease:
    def __init__(self,state,physical):
        object.__setattr__(self,'_state',state);object.__setattr__(self,'_physical',physical)
        object.__setattr__(self,'_closed',False);object.__setattr__(self,'_cursors',weakref.WeakSet())
        state['leases'].add(self)
    def _check(self):
        if (self._closed or self._state['closed'] or self._state['key']!=_request_key()
                or self._physical['retired']):
            raise sqlite3.ProgrammingError('Cannot operate on a closed or foreign request connection.')
    def close(self):
        if self._closed:return
        self._check();object.__setattr__(self,'_closed',True)
        for cursor in list(self._cursors):cursor.close()
        physical=self._physical;c=physical['connection']
        if c.in_transaction:
            physical['dirty']=True;c.rollback()
        if (physical['dirty'] or c.total_changes or len(self._state['idle'])>=MAX_IDLE):
            _retire(self._state,physical)
        else:self._state['idle'].append(physical)
    def __enter__(self):self._check();self._physical['connection'].__enter__();return self
    def __exit__(self,*args):self._check();return self._physical['connection'].__exit__(*args)
    def execute(self,*args,**kwargs):
        self._check();return Cursor(self,self._physical['connection'].execute(*args,**kwargs))
    def executemany(self,*args,**kwargs):
        self._check();return Cursor(self,self._physical['connection'].executemany(*args,**kwargs))
    def executescript(self,*args,**kwargs):
        self._check();return Cursor(self,self._physical['connection'].executescript(*args,**kwargs))
    def cursor(self,*args,**kwargs):
        self._check();return Cursor(self,self._physical['connection'].cursor(*args,**kwargs))
    def __getattr__(self,name):
        self._check();value=getattr(self._physical['connection'],name)
        if getattr(value,'__self__',None) is not self._physical['connection']:return value
        def call(*args,**kwargs):
            self._check()
            if name not in {'commit','rollback','interrupt'}:self._physical['dirty']=True
            return value(*args,**kwargs)
        return call
    def __setattr__(self,name,value):
        if name.startswith('_'):object.__setattr__(self,name,value)
        else:
            self._check();self._physical['dirty']=True
            setattr(self._physical['connection'],name,value)

def borrow(factory,*,database=None):
    from flask import g,has_request_context,request
    if (not has_request_context() or request.method!='GET' or not (
            request.path in ('/student/learn-vnext','/student/chapter')
            or request.path.startswith('/student/subject/') or request.path.startswith('/student/catalogue/'))):
        return factory()
    key=_request_key();target=str(Path(database).resolve()) if database is not None else None
    domain=(key,_factory_identity(factory),target)
    states=getattr(g,KEY,None)
    if states is None:states={};setattr(g,KEY,states)
    state=states.get(domain)
    if state is None:
        state={'key':key,'idle':[],'all':{},'leases':weakref.WeakSet(),'closed':False,
            'target':target,'factory_identity':_factory_identity(factory),'factory_ref':factory}
        states[domain]=state
        if target:
            previous=_take_idle(factory,target)
            if previous is not None:
                state['all'][id(previous['connection'])]=previous;state['idle'].append(previous)
    while state['idle']:
        physical=state['idle'].pop()
        try:current=_current_identity(physical['identity'])
        except OSError:current=None
        if current is None or current!=physical['identity']:
            _retire(state,physical);continue
        return Lease(state,physical)
    if len(state['all'])>=MAX_PHYSICAL:return factory()
    c=factory()
    try:identity=_identity(c)
    except (sqlite3.Error,OSError):return c
    if identity is None:return c
    physical={'connection':c,'identity':identity,'dirty':False,'retired':False}
    state['all'][id(c)]=physical
    def authorize(action,arg1,arg2,database,trigger):
        if action==sqlite3.SQLITE_PRAGMA:
            safe=(str(arg1).lower() in READ_PRAGMAS
                  or (arg2 is None and str(arg1).lower() in READ_ONLY_GETTERS))
        else:safe=action in READ_ACTIONS
        if not safe:physical['dirty']=True
        return sqlite3.SQLITE_OK  # Native permissions/transactions stay authoritative.
    c.set_authorizer(authorize)
    return Lease(state,physical)

def install(app):
    if app.extensions.get('navigation_request_connections_v1'):return
    app.extensions['navigation_request_connections_v1']=True
    @app.teardown_request
    def close_navigation_connections(error=None):
        from flask import g
        states=getattr(g,KEY,None)
        if not states:return
        for domain,state in list(states.items()):
            if state['key']!=_request_key():continue
            states.pop(domain,None)
            for lease in list(state['leases']):
                if not lease._closed:
                    try:lease.close()
                    except sqlite3.Error:pass
            state['closed']=True
            kept=False
            for physical in list(state['all'].values()):
                if not kept and _keep_idle(state,physical):
                    kept=True;state['all'].pop(id(physical['connection']),None)
                else:_retire(state,physical)
            state['idle'].clear()

